o:[{hi:'20L',en:'20L'},{hi:'30L',en:'30L'},{hi:'35L',en:'35L'},{hi:'25L',en:'25L'}],a:1,src:{hi:'RRB NTPC 2021',en:'RRB NTPC 2021'},
