o:[{hi:'20, 30',en:'20, 30'},{hi:'21, 29',en:'21, 29'},{hi:'18, 32',en:'18, 32'},{hi:'22, 28',en:'22, 28'}],a:1,src:{hi:'RRB Group D 2018',en:'RRB Group D 2018'},
