o:[{hi:'16 वर्ष',en:'16 years'},{hi:'20 वर्ष',en:'20 years'},{hi:'12 वर्ष',en:'12 years'},{hi:'24 वर्ष',en:'24 years'}],a:0,src:{hi:'RRB ALP 2018',en:'RRB ALP 2018'},
